# forensic_toolkit.py - Combined Forensic Search Platform with 9-Panel Grid Layout

import sys
import os
import webbrowser
import requests
import tempfile
import subprocess
import time
import re
from bs4 import BeautifulSoup
from urllib.parse import quote_plus
from PyQt6.QtWidgets import (QApplication, QWidget, QVBoxLayout, QHBoxLayout, QLabel, 
                              QLineEdit, QPushButton, QTextBrowser, QCheckBox, QFileDialog, 
                              QComboBox, QGridLayout, QScrollArea, QFrame, QSizePolicy)
from PyQt6.QtGui import QPixmap, QImage, QIcon, QFont
from PyQt6.QtCore import Qt, QSize, QThreadPool, QRunnable, pyqtSignal, QObject

# ============================================================================
# SEARCH SCRAPER MODULE
# ============================================================================

HEADERS = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/119.0.0.0 Safari/537.36"
}

def search_google(query, num_results=10):
    results = []
    q = quote_plus(query)
    for start in range(0, num_results, 10):
        url = f"https://www.google.com/search?q={q}&start={start}"
        try:
            res = requests.get(url, headers=HEADERS, timeout=10)
            soup = BeautifulSoup(res.text, 'html.parser')
            for a in soup.select('a'):
                href = a.get('href')
                if href and href.startswith('/url?q='):
                    link = href.split('/url?q=')[1].split('&')[0]
                    if 'webcache' not in link and 'google' not in link:
                        results.append(link)
            time.sleep(1)
        except:
            pass
    return list(set(results))

def search_bing(query, num_results=10):
    results = []
    q = quote_plus(query)
    for page in range(0, num_results, 10):
        url = f"https://www.bing.com/search?q={q}&first={page}"
        try:
            res = requests.get(url, headers=HEADERS, timeout=10)
            soup = BeautifulSoup(res.text, 'html.parser')
            for li in soup.select('li.b_algo h2 a'):
                href = li.get('href')
                if href:
                    results.append(href)
            time.sleep(1)
        except:
            pass
    return list(set(results))

def search_yahoo(query, num_results=10):
    results = []
    q = quote_plus(query)
    for i in range(0, num_results, 10):
        url = f"https://search.yahoo.com/search?p={q}&b={i}"
        try:
            res = requests.get(url, headers=HEADERS, timeout=10)
            soup = BeautifulSoup(res.text, 'html.parser')
            for a in soup.select('h3.title a'):
                href = a.get('href')
                if href:
                    results.append(href)
            time.sleep(1)
        except:
            pass
    return list(set(results))

def search_yandex(query, num_results=10):
    results = []
    q = quote_plus(query)
    for page in range(num_results // 10):
        url = f"https://yandex.com/search/?text={q}&p={page}"
        try:
            res = requests.get(url, headers=HEADERS, timeout=10)
            soup = BeautifulSoup(res.text, 'html.parser')
            for a in soup.select('a.link.link_theme_normal'):
                href = a.get('href')
                if href and 'yabs' not in href:
                    results.append(href)
            time.sleep(1)
        except:
            pass
    return list(set(results))

def search_google_drive(query):
    return search_google(f"site:drive.google.com {query}")

def search_dropbox(query):
    return search_google(f"site:dropbox.com {query}")

def search_photobucket(query):
    return search_google(f"site:photobucket.com {query}")

def search_imgur(query):
    return search_google(f"site:imgur.com {query}")

def search_tumblr(query):
    return search_google(f"site:tumblr.com {query}")

def search_reddit(query):
    return search_google(f"site:reddit.com {query}")

def search_pornhub(query, base_url="https://www.pornhub.com"):
    q = quote_plus(query)
    url = f"{base_url}/video/search?search={q}"
    results = []
    try:
        res = requests.get(url, headers=HEADERS, timeout=10)
        soup = BeautifulSoup(res.text, 'html.parser')
        for a in soup.select('a.linkVideoThumb'):
            href = a.get('href')
            title = a.get('title', '')
            if href:
                results.append({"url": base_url + href, "title": title})
    except:
        pass
    return results

def search_xvideos(query, base_url="https://www.xvideos.com"):
    q = quote_plus(query)
    url = f"{base_url}/?k={q}"
    results = []
    try:
        res = requests.get(url, headers=HEADERS, timeout=10)
        soup = BeautifulSoup(res.text, 'html.parser')
        for a in soup.select('a.thumb'):
            href = a.get('href')
            title = a.get('title', '')
            if href:
                results.append({"url": base_url + href, "title": title})
    except:
        pass
    return results

def search_xnxx(query, base_url="https://www.xnxx.com"):
    q = quote_plus(query)
    url = f"{base_url}/search/{q}"
    results = []
    try:
        res = requests.get(url, headers=HEADERS, timeout=10)
        soup = BeautifulSoup(res.text, 'html.parser')
        for a in soup.select('a.thumb'):
            href = a.get('href')
            if href:
                results.append({"url": base_url + href})
    except:
        pass
    return results

def search_motherless(query, base_url="https://motherless.com"):
    q = quote_plus(query)
    url = f"{base_url}/term/{q}"
    results = []
    try:
        res = requests.get(url, headers=HEADERS, timeout=10)
        soup = BeautifulSoup(res.text, 'html.parser')
        for a in soup.select('a.img-container'):
            href = a.get('href')
            img_tag = a.select_one('img')
            if href:
                full_url = href if href.startswith('http') else base_url + href
                preview_url = img_tag['data-src'] if img_tag and img_tag.has_attr('data-src') else None
                results.append({"url": full_url, "preview": preview_url})
    except:
        pass
    return results

def search_nudevista(query, base_url="https://www.nudevista.com"):
    q = quote_plus(query)
    url = f"{base_url}/?q={q}"
    results = []
    try:
        res = requests.get(url, headers=HEADERS, timeout=10)
        soup = BeautifulSoup(res.text, 'html.parser')
        for a in soup.select('a[href*="/video/"]'):
            href = a.get('href')
            if href:
                results.append({"url": href if href.startswith('http') else base_url + href})
    except:
        pass
    return results

def parse_pornhub_playlists(query, base_url="https://www.pornhub.com"):
    q = quote_plus(query)
    results = []
    playlist_url = f"{base_url}/users/{q}/playlists"
    try:
        res = requests.get(playlist_url, headers=HEADERS, timeout=10)
        soup = BeautifulSoup(res.text, 'html.parser')
        for a in soup.select('a.playlistPreview'):
            href = a.get('href')
            if href:
                results.append(base_url + href)
    except:
        pass
    return results

def parse_xvideos_playlists(query, base_url="https://www.xvideos.com"):
    q = quote_plus(query)
    results = []
    playlist_url = f"{base_url}/profiles/{q}/playlists"
    try:
        res = requests.get(playlist_url, headers=HEADERS, timeout=10)
        soup = BeautifulSoup(res.text, 'html.parser')
        for a in soup.select('div.thumb a[href*="playlist"]'):
            href = a.get('href')
            if href:
                results.append(base_url + href)
    except:
        pass
    return results

def parse_motherless_collections(query, base_url="https://motherless.com"):
    q = quote_plus(query)
    results = []
    try:
        url = f"{base_url}/G/{q}"
        res = requests.get(url, headers=HEADERS, timeout=10)
        soup = BeautifulSoup(res.text, 'html.parser')
        for a in soup.select('a[href^="/G/"]'):
            href = a.get('href')
            if href and '/G/' in href:
                results.append(base_url + href)
    except:
        pass
    return results

# ============================================================================
# SEARCH AGGREGATOR
# ============================================================================

def run_all_searches(query, mode="all"):
    all_results = []
    if mode in ["all", "images"]:
        all_results += search_google(query, 10)
        all_results += search_bing(query, 10)
        all_results += search_yahoo(query, 10)
        all_results += search_yandex(query, 10)
        all_results += search_google_drive(query)
        all_results += search_dropbox(query)
        all_results += search_photobucket(query)
        all_results += search_imgur(query)
        all_results += search_tumblr(query)
        all_results += search_reddit(query)

    if mode in ["all", "videos"]:
        all_results += [r['url'] for r in search_pornhub(query)]
        all_results += [r['url'] for r in search_xvideos(query)]
        all_results += [r['url'] for r in search_xnxx(query)]
        all_results += [r['url'] for r in search_motherless(query)]
        all_results += [r['url'] for r in search_nudevista(query)]
        all_results += parse_pornhub_playlists(query)
        all_results += parse_xvideos_playlists(query)
        all_results += parse_motherless_collections(query)

    return list(set(all_results))

# ============================================================================
# PREVIEW HELPERS
# ============================================================================

def get_preview_image(url):
    try:
        headers = {"User-Agent": "Mozilla/5.0"}
        res = requests.get(url, headers=headers, timeout=5)
        if res.status_code != 200:
            return None
        html = res.text
        for tag in ["og:image", "twitter:image", "image"]:
            idx = html.find(f'property="{tag}"')
            if idx == -1:
                continue
            content_idx = html.find('content="', idx)
            if content_idx == -1:
                continue
            start = content_idx + 9
            end = html.find('"', start)
            return html[start:end]
    except:
        return None

def extract_video_preview(url):
    try:
        temp_dir = tempfile.mkdtemp()
        output_path = os.path.join(temp_dir, "preview.jpg")
        command = ["ffmpeg", "-y", "-i", url, "-ss", "00:00:02.000", "-vframes", "1", output_path]
        subprocess.run(command, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=15)
        return output_path if os.path.exists(output_path) else None
    except:
        return None

# ============================================================================
# PREVIEW CARD WIDGET
# ============================================================================

class PreviewCard(QFrame):
    clicked = pyqtSignal(str)
    checked_changed = pyqtSignal(str, bool)

    def __init__(self, url, parent=None):
        super().__init__(parent)
        self.url = url
        self.is_checked = False
        self.setFrameStyle(QFrame.Shape.Box | QFrame.Shadow.Raised)
        self.setLineWidth(1)
        self.setMinimumSize(250, 200)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.setStyleSheet("""
            PreviewCard {
                background-color: #2d2d2d;
                border: 2px solid #444;
                border-radius: 8px;
            }
            PreviewCard:hover {
                border: 2px solid #0078d4;
            }
        """)

        layout = QVBoxLayout(self)
        layout.setContentsMargins(5, 5, 5, 5)
        layout.setSpacing(5)

        self.image_label = QLabel()
        self.image_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.image_label.setMinimumHeight(140)
        self.image_label.setStyleSheet("background-color: #1a1a1a; border-radius: 4px;")
        self.image_label.setText("Loading...")

        self.url_label = QLabel()
        self.url_label.setWordWrap(True)
        self.url_label.setMaximumHeight(40)
        self.url_label.setStyleSheet("color: #aaa; font-size: 10px;")
        display_url = url[:60] + "..." if len(url) > 60 else url
        self.url_label.setText(display_url)

        self.checkbox = QCheckBox("Select")
        self.checkbox.setStyleSheet("color: #fff;")
        self.checkbox.stateChanged.connect(self._on_check_changed)

        layout.addWidget(self.image_label, stretch=1)
        layout.addWidget(self.url_label)
        layout.addWidget(self.checkbox)

    def set_preview(self, pixmap):
        if pixmap and not pixmap.isNull():
            scaled = pixmap.scaled(QSize(240, 135), Qt.AspectRatioMode.KeepAspectRatio, 
                                   Qt.TransformationMode.SmoothTransformation)
            self.image_label.setPixmap(scaled)
        else:
            self.image_label.setText("No Preview")

    def _on_check_changed(self, state):
        self.is_checked = state == Qt.CheckState.Checked.value
        self.checked_changed.emit(self.url, self.is_checked)

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.clicked.emit(self.url)
        super().mousePressEvent(event)

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            webbrowser.open(self.url)
        super().mouseDoubleClickEvent(event)

# ============================================================================
# WORKER SIGNALS & THREADS
# ============================================================================

class WorkerSignals(QObject):
    finished = pyqtSignal()
    result = pyqtSignal(str, object)
    progress = pyqtSignal(int, int)

class SearchWorker(QRunnable):
    def __init__(self, query, download_previews, mode):
        super().__init__()
        self.query = query
        self.download_previews = download_previews
        self.mode = mode
        self.signals = WorkerSignals()

    def run(self):
        results = run_all_searches(self.query, self.mode)
        total = len(results)
        for i, url in enumerate(results):
            pixmap = None
            if self.download_previews:
                preview_url = get_preview_image(url)
                if preview_url:
                    try:
                        img_data = requests.get(preview_url, timeout=5).content
                        image = QImage()
                        if image.loadFromData(img_data) and not image.isNull():
                            pixmap = QPixmap.fromImage(image)
                    except:
                        pass
                elif url.endswith(('.mp4', '.webm')):
                    thumb = extract_video_preview(url)
                    if thumb:
                        image = QImage(thumb)
                        if not image.isNull():
                            pixmap = QPixmap.fromImage(image)
            self.signals.result.emit(url, pixmap)
            self.signals.progress.emit(i + 1, total)
        self.signals.finished.emit()

# ============================================================================
# MAIN GUI - 9 PANEL GRID LAYOUT
# ============================================================================

class ForensicSearchGUI(QWidget):
    def __init__(self):
        super().__init__()
        self.setWindowTitle("Forensic Search Toolkit - 9 Panel Grid")
        self.setGeometry(100, 100, 1400, 900)
        self.setStyleSheet("""
            QWidget {
                background-color: #1e1e1e;
                color: #ffffff;
                font-family: Segoe UI, Arial;
            }
            QLineEdit {
                background-color: #2d2d2d;
                border: 1px solid #444;
                border-radius: 4px;
                padding: 8px;
                color: #fff;
            }
            QPushButton {
                background-color: #0078d4;
                border: none;
                border-radius: 4px;
                padding: 8px 16px;
                color: #fff;
                font-weight: bold;
            }
            QPushButton:hover {
                background-color: #1084d8;
            }
            QPushButton:disabled {
                background-color: #444;
            }
            QComboBox {
                background-color: #2d2d2d;
                border: 1px solid #444;
                border-radius: 4px;
                padding: 6px;
                color: #fff;
            }
            QCheckBox {
                color: #fff;
            }
            QScrollArea {
                border: none;
            }
        """)

        self.thread_pool = QThreadPool()
        self.preview_cards = []
        self.selected_urls = set()
        self.current_page = 0
        self.all_results = []

        main_layout = QVBoxLayout(self)
        main_layout.setSpacing(10)

        # Header
        header = QLabel("🔍 Forensic Search Toolkit")
        header.setFont(QFont("Segoe UI", 18, QFont.Weight.Bold))
        header.setAlignment(Qt.AlignmentFlag.AlignCenter)
        main_layout.addWidget(header)

        # Search controls
        controls_layout = QHBoxLayout()
        self.search_input = QLineEdit()
        self.search_input.setPlaceholderText("Enter forensic search term (username, tag, IP, etc.)")
        self.search_input.returnPressed.connect(self.execute_search)

        self.mode_selector = QComboBox()
        self.mode_selector.addItems(["all", "images", "videos"])

        self.search_button = QPushButton("Search")
        self.search_button.clicked.connect(self.execute_search)

        self.download_checkbox = QCheckBox("Download Previews")
        self.download_checkbox.setChecked(True)

        controls_layout.addWidget(self.search_input, stretch=3)
        controls_layout.addWidget(self.mode_selector)
        controls_layout.addWidget(self.download_checkbox)
        controls_layout.addWidget(self.search_button)
        main_layout.addLayout(controls_layout)

        # Progress label
        self.progress_label = QLabel("")
        self.progress_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.progress_label.setStyleSheet("color: #888;")
        main_layout.addWidget(self.progress_label)

        # 9-panel grid in scroll area
        scroll_area = QScrollArea()
        scroll_area.setWidgetResizable(True)
        scroll_area.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)

        self.grid_container = QWidget()
        self.grid_layout = QGridLayout(self.grid_container)
        self.grid_layout.setSpacing(10)
        self.grid_layout.setContentsMargins(10, 10, 10, 10)

        scroll_area.setWidget(self.grid_container)
        main_layout.addWidget(scroll_area, stretch=1)

        # Pagination
        pagination_layout = QHBoxLayout()
        self.prev_button = QPushButton("◀ Previous")
        self.prev_button.clicked.connect(self.prev_page)
        self.page_label = QLabel("Page 1")
        self.page_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.next_button = QPushButton("Next ▶")
        self.next_button.clicked.connect(self.next_page)

        pagination_layout.addWidget(self.prev_button)
        pagination_layout.addWidget(self.page_label, stretch=1)
        pagination_layout.addWidget(self.next_button)
        main_layout.addLayout(pagination_layout)

        # Bottom controls
        bottom_layout = QHBoxLayout()
        self.export_button = QPushButton("Export Selected URLs")
        self.export_button.clicked.connect(self.export_selected)
        self.open_button = QPushButton("Open Selected in Browser")
        self.open_button.clicked.connect(self.open_selected_in_browser)
        self.select_all_button = QPushButton("Select All on Page")
        self.select_all_button.clicked.connect(self.select_all_on_page)

        bottom_layout.addWidget(self.select_all_button)
        bottom_layout.addWidget(self.export_button)
        bottom_layout.addWidget(self.open_button)
        main_layout.addLayout(bottom_layout)

        # Preview panel
        self.preview_box = QTextBrowser()
        self.preview_box.setMaximumHeight(80)
        self.preview_box.setStyleSheet("background-color: #2d2d2d; border-radius: 4px; padding: 8px;")
        main_layout.addWidget(self.preview_box)

        self.result_data = {}

    def execute_search(self):
        self.clear_grid()
        self.all_results = []
        self.result_data = {}
        self.current_page = 0
        self.selected_urls.clear()

        query = self.search_input.text().strip()
        if not query:
            return

        self.search_button.setText("Searching...")
        self.search_button.setEnabled(False)
        self.progress_label.setText("Searching...")

        mode = self.mode_selector.currentText()
        worker = SearchWorker(query, self.download_checkbox.isChecked(), mode)
        worker.signals.result.connect(self.add_result)
        worker.signals.progress.connect(self.update_progress)
        worker.signals.finished.connect(self.search_done)
        self.thread_pool.start(worker)

    def add_result(self, url, pixmap):
        self.all_results.append((url, pixmap))
        self.result_data[url] = pixmap
        if len(self.all_results) <= 9:
            self.display_page(0)

    def update_progress(self, current, total):
        self.progress_label.setText(f"Loading: {current}/{total} results")

    def search_done(self):
        self.search_button.setText("Search")
        self.search_button.setEnabled(True)
        self.display_page(0)
        total_pages = (len(self.all_results) + 8) // 9
        self.progress_label.setText(f"Found {len(self.all_results)} results ({total_pages} pages)")

    def clear_grid(self):
        for card in self.preview_cards:
            card.deleteLater()
        self.preview_cards.clear()

    def display_page(self, page_num):
        self.clear_grid()
        self.current_page = page_num

        start_idx = page_num * 9
        end_idx = min(start_idx + 9, len(self.all_results))
        page_results = self.all_results[start_idx:end_idx]

        for i, (url, pixmap) in enumerate(page_results):
            row = i // 3
            col = i % 3

            card = PreviewCard(url)
            card.set_preview(pixmap)
            card.clicked.connect(self.on_card_clicked)
            card.checked_changed.connect(self.on_card_checked)

            if url in self.selected_urls:
                card.checkbox.setChecked(True)

            self.grid_layout.addWidget(card, row, col)
            self.preview_cards.append(card)

        total_pages = max(1, (len(self.all_results) + 8) // 9)
        self.page_label.setText(f"Page {page_num + 1} of {total_pages}")
        self.prev_button.setEnabled(page_num > 0)
        self.next_button.setEnabled(end_idx < len(self.all_results))

    def prev_page(self):
        if self.current_page > 0:
            self.display_page(self.current_page - 1)

    def next_page(self):
        max_page = (len(self.all_results) - 1) // 9
        if self.current_page < max_page:
            self.display_page(self.current_page + 1)

    def on_card_clicked(self, url):
        self.preview_box.setText(f"Selected: {url}")

    def on_card_checked(self, url, checked):
        if checked:
            self.selected_urls.add(url)
        else:
            self.selected_urls.discard(url)

    def select_all_on_page(self):
        for card in self.preview_cards:
            card.checkbox.setChecked(True)

    def export_selected(self):
        if not self.selected_urls:
            self.preview_box.setText("No URLs selected for export.")
            return

        filename, _ = QFileDialog.getSaveFileName(
            self, "Save Selected URLs", "selected_urls.txt", "Text Files (*.txt)"
        )
        if filename:
            with open(filename, 'w') as f:
                for url in self.selected_urls:
                    f.write(url + "\n")
            self.preview_box.setText(f"Exported {len(self.selected_urls)} URLs to {filename}")

    def open_selected_in_browser(self):
        for url in self.selected_urls:
            webbrowser.open(url)

# ============================================================================
# MAIN ENTRY POINT
# ============================================================================

if __name__ == '__main__':
    app = QApplication(sys.argv)
    gui = ForensicSearchGUI()
    gui.show()
    sys.exit(app.exec())

