from PyQt6.QtWidgets import (QApplication, QWidget, QVBoxLayout, QHBoxLayout, QLabel, 
                              QLineEdit, QPushButton, QTextBrowser, QCheckBox, QFileDialog, 
                              QComboBox, QGridLayout, QScrollArea, QFrame, QSizePolicy)
