def get_preview_image(url):
    try:
        headers = {"User-Agent": "Mozilla/5.0"}
        res = requests.get(url, headers=headers, timeout=5)
        if res.status_code != 200:
            return None
        html = res.text
        for tag in ["og:image", "twitter:image", "image"]:
            idx = html.find(f'property="{tag}"')
            if idx == -1:
                continue
            content_idx = html.find('content="', idx)
            if content_idx == -1:
                continue
            start = content_idx + 9
            end = html.find('"', start)
            return html[start:end]
    except:
        return None

def extract_video_preview(url):
    try:
        temp_dir = tempfile.mkdtemp()
        output_path = os.path.join(temp_dir, "preview.jpg")
        command = ["ffmpeg", "-y", "-i", url, "-ss", "00:00:02.000", "-vframes", "1", output_path]
        subprocess.run(command, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=15)
        return output_path if os.path.exists(output_path) else None
    except:
        return None

