class PreviewCard(QFrame):
    clicked = pyqtSignal(str)
    checked_changed = pyqtSignal(str, bool)

    def __init__(self, url, parent=None):
        super().__init__(parent)
        self.url = url
        self.is_checked = False
        self.setFrameStyle(QFrame.Shape.Box | QFrame.Shadow.Raised)
        self.setLineWidth(1)
        self.setMinimumSize(250, 200)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.setStyleSheet("""
            PreviewCard {
                background-color: #2d2d2d;
                border: 2px solid #444;
                border-radius: 8px;
            }
            PreviewCard:hover {
                border: 2px solid #0078d4;
            }
        """)

        layout = QVBoxLayout(self)
        layout.setContentsMargins(5, 5, 5, 5)
        layout.setSpacing(5)

        self.image_label = QLabel()
        self.image_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.image_label.setMinimumHeight(140)
        self.image_label.setStyleSheet("background-color: #1a1a1a; border-radius: 4px;")
        self.image_label.setText("Loading...")

        self.url_label = QLabel()
        self.url_label.setWordWrap(True)
        self.url_label.setMaximumHeight(40)
        self.url_label.setStyleSheet("color: #aaa; font-size: 10px;")
        display_url = url[:60] + "..." if len(url) > 60 else url
        self.url_label.setText(display_url)

        self.checkbox = QCheckBox("Select")
        self.checkbox.setStyleSheet("color: #fff;")
        self.checkbox.stateChanged.connect(self._on_check_changed)

        layout.addWidget(self.image_label, stretch=1)
        layout.addWidget(self.url_label)
        layout.addWidget(self.checkbox)

    def set_preview(self, pixmap):
        if pixmap and not pixmap.isNull():
            scaled = pixmap.scaled(QSize(240, 135), Qt.AspectRatioMode.KeepAspectRatio, 
                                   Qt.TransformationMode.SmoothTransformation)
            self.image_label.setPixmap(scaled)
        else:
            self.image_label.setText("No Preview")

    def _on_check_changed(self, state):
        self.is_checked = state == Qt.CheckState.Checked.value
        self.checked_changed.emit(self.url, self.is_checked)

    def mousePressEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            self.clicked.emit(self.url)
        super().mousePressEvent(event)

    def mouseDoubleClickEvent(self, event):
        if event.button() == Qt.MouseButton.LeftButton:
            webbrowser.open(self.url)
        super().mouseDoubleClickEvent(event)

