# ============================================================================

class WorkerSignals(QObject):
    finished = pyqtSignal()
    result = pyqtSignal(str, object)
    progress = pyqtSignal(int, int)

class SearchWorker(QRunnable):
    def __init__(self, query, download_previews, mode):
        super().__init__()
        self.query = query
        self.download_previews = download_previews
        self.mode = mode
        self.signals = WorkerSignals()

    def run(self):
        results = run_all_searches(self.query, self.mode)
        total = len(results)
        for i, url in enumerate(results):
            pixmap = None
            if self.download_previews:
                preview_url = get_preview_image(url)
                if preview_url:
                    try:
                        img_data = requests.get(preview_url, timeout=5).content
                        image = QImage()
                        if image.loadFromData(img_data) and not image.isNull():
                            pixmap = QPixmap.fromImage(image)
                    except:
                        pass
                elif url.endswith(('.mp4', '.webm')):
                    thumb = extract_video_preview(url)
                    if thumb:
                        image = QImage(thumb)
                        if not image.isNull():
                            pixmap = QPixmap.fromImage(image)
            self.signals.result.emit(url, pixmap)
            self.signals.progress.emit(i + 1, total)
        self.signals.finished.emit()

