    def execute_search(self):
        self.clear_grid()
        self.all_results = []
        self.result_data = {}
        self.current_page = 0
        self.selected_urls.clear()

        query = self.search_input.text().strip()
        if not query:
            return

        self.search_button.setText("Searching...")
        self.search_button.setEnabled(False)
        self.progress_label.setText("Searching...")

        mode = self.mode_selector.currentText()
        worker = SearchWorker(query, self.download_checkbox.isChecked(), mode)
        worker.signals.result.connect(self.add_result)
        worker.signals.progress.connect(self.update_progress)
        worker.signals.finished.connect(self.search_done)
        self.thread_pool.start(worker)

    def add_result(self, url, pixmap):
        self.all_results.append((url, pixmap))
        self.result_data[url] = pixmap
        if len(self.all_results) <= 9:
            self.display_page(0)

    def update_progress(self, current, total):
        self.progress_label.setText(f"Loading: {current}/{total} results")

    def search_done(self):
        self.search_button.setText("Search")
        self.search_button.setEnabled(True)
        self.display_page(0)
        total_pages = (len(self.all_results) + 8) // 9
        self.progress_label.setText(f"Found {len(self.all_results)} results ({total_pages} pages)")

    def clear_grid(self):
        for card in self.preview_cards:
            card.deleteLater()
        self.preview_cards.clear()

    def display_page(self, page_num):
        self.clear_grid()
        self.current_page = page_num

        start_idx = page_num * 9
        end_idx = min(start_idx + 9, len(self.all_results))
        page_results = self.all_results[start_idx:end_idx]

        for i, (url, pixmap) in enumerate(page_results):
            row = i // 3
            col = i % 3

            card = PreviewCard(url)
            card.set_preview(pixmap)
            card.clicked.connect(self.on_card_clicked)
            card.checked_changed.connect(self.on_card_checked)

            if url in self.selected_urls:
                card.checkbox.setChecked(True)

            self.grid_layout.addWidget(card, row, col)
            self.preview_cards.append(card)

        total_pages = max(1, (len(self.all_results) + 8) // 9)
        self.page_label.setText(f"Page {page_num + 1} of {total_pages}")
        self.prev_button.setEnabled(page_num > 0)
        self.next_button.setEnabled(end_idx < len(self.all_results))

    def prev_page(self):
        if self.current_page > 0:
            self.display_page(self.current_page - 1)

    def next_page(self):
        max_page = (len(self.all_results) - 1) // 9
        if self.current_page < max_page:
            self.display_page(self.current_page + 1)

    def on_card_clicked(self, url):
        self.preview_box.setText(f"Selected: {url}")

    def on_card_checked(self, url, checked):
        if checked:
            self.selected_urls.add(url)
        else:
            self.selected_urls.discard(url)

    def select_all_on_page(self):
        for card in self.preview_cards:
            card.checkbox.setChecked(True)

    def export_selected(self):
        if not self.selected_urls:
            self.preview_box.setText("No URLs selected for export.")
            return

        filename, _ = QFileDialog.getSaveFileName(
            self, "Save Selected URLs", "selected_urls.txt", "Text Files (*.txt)"
        )
        if filename:
            with open(filename, 'w') as f:
                for url in self.selected_urls:
                    f.write(url + "\n")
            self.preview_box.setText(f"Exported {len(self.selected_urls)} URLs to {filename}")

    def open_selected_in_browser(self):
        for url in self.selected_urls:
            webbrowser.open(url)

